t.script:
//
(function() {
    'use strict';

    var container = null;
    var variantsData = [];
    var translations = {};
    var lastConfirmedVariantId = null;

    function init() {
        container = document.getElementById('lcn-stock-container');
        if (!container) return;

        var dataAttr = container.getAttribute('data-variants');
        if (dataAttr) {
            try {
                variantsData = JSON.parse(dataAttr);
            } catch (e) {
                console.error('[LCN] Error JSON:', e);
            }
        }

        var transEl = document.getElementById('lcn-translations');
        if (transEl) {
            translations = {
                in_stock: transEl.getAttribute('data-in-stock') || 'En stock',
                in_stock_plural: transEl.getAttribute('data-in-stock-plural') || 'unidades disponibles',
                low_stock_title: transEl.getAttribute('data-low-stock-title') || '¡Últimas unidades!',
                low_stock_plural: transEl.getAttribute('data-low-stock-plural') || 'disponibles',
                low_stock_singular: transEl.getAttribute('data-low-stock-singular') || 'disponible',
                out_of_stock: transEl.getAttribute('data-out-of-stock') || 'Producto agotado',
                out_of_stock_subtitle: transEl.getAttribute('data-out-of-stock-subtitle') || 'Consúltanos por disponibilidad',
                only: transEl.getAttribute('data-only') || 'solo'
            };
        }

        actualizarBadge();
        eliminarMensajeAmarillo();
    }

    function t(key, fallback) {
        return translations[key] || fallback;
    }

    function renderBadge(qty) {
        var html = '';
        if (qty > 10) {
            html = '<div class="lcn-stock-badge lcn-in-stock">' +
                '<span class="lcn-icon"><i class="fa fa-check-circle"></i></span>' +
                '<span><strong>' + t('in_stock', 'En stock') + '</strong> — ' +
                '<span class="lcn-quantity">' + Math.floor(qty) + '</span> ' +
                t('in_stock_plural', 'unidades disponibles') +
                '</span></div>';
        } else if (qty > 0) {
            var p = qty !== 1 ? t('low_stock_plural', 'disponibles') : t('low_stock_singular', 'disponible');
            html = '<div class="lcn-stock-badge lcn-low-stock">' +
                '<span class="lcn-icon"><i class="fa fa-fire"></i></span>' +
                '<span><strong>' + t('low_stock_title', '¡Últimas unidades!') + '</strong> — ' +
                t('only', 'solo') + ' <span class="lcn-quantity">' + Math.floor(qty) + '</span> ' + p +
                '</span></div>';
        } else {
            html = '<div class="lcn-stock-badge lcn-out-of-stock">' +
                '<span class="lcn-icon"><i class="fa fa-times-circle"></i></span>' +
                '<span><strong>' + t('out_of_stock', 'Producto agotado') + '</strong> — ' +
                t('out_of_stock_subtitle', 'Consúltanos por disponibilidad') +
                '</span></div>';
        }
        return html;
    }

    function getCurrentVariantId() {
        var input = document.querySelector('input[name="product_id"]');
        if (input && input.value && parseInt(input.value) > 0) return parseInt(input.value);

        var productIdInput = document.querySelector('.js_product input[name="product_id"]');
        if (productIdInput && productIdInput.value && parseInt(productIdInput.value) > 0) return parseInt(productIdInput.value);

        var productEl = document.querySelector('[data-product-id]');
        if (productEl) return parseInt(productEl.getAttribute('data-product-id'));

        // Try to get from Odoo's public API if available
        if (window.publicWidget && window.publicWidget.registry) {
            var variantSelector = window.publicWidget.registry.VariantMixin;
            if (variantSelector && variantSelector.currentProductId) {
                return variantSelector.currentProductId;
            }
        }

        return null;
    }

    function actualizarBadge(reintentos) {
        if (!container) return;

        var placeholder = document.getElementById('lcn-stock-placeholder');
        var variantId = getCurrentVariantId();
        var variant = null;

        // Si tenemos ID de variante, buscar en los datos
        if (variantId) {
            for (var i = 0; i < variantsData.length; i++) {
                if (variantsData[i].id === variantId) {
                    variant = variantsData[i];
                    break;
                }
            }
        }

        // RACE: si la variante coincide con la ultima pintada, el input
        // todavia puede tener el valor anterior. Reintentar hasta confirmar.
        if (variant && variant.id === lastConfirmedVariantId &&
            (reintentos === undefined || reintentos > 0)) {
            var siguienteIntento = (reintentos === undefined) ? 6 : reintentos - 1;
            setTimeout(function () { actualizarBadge(siguienteIntento); }, 100);
            return;
        }

        // Si no hay variante detectada y tenemos reintentos disponibles
        if (!variant && (reintentos === undefined || reintentos > 0)) {
            // Mostrar placeholder de carga
            if (placeholder) {
                container.querySelectorAll('.lcn-stock-badge').forEach(function(el) { el.style.display = 'none'; });
                placeholder.style.display = 'block';
            }

            var siguienteIntento = (reintentos === undefined) ? 10 : reintentos - 1;
            setTimeout(function() { actualizarBadge(siguienteIntento); }, 100);
            return;
        }

        // Ocultar placeholder
        if (placeholder) placeholder.style.display = 'none';

        // Fallback solo si no hay reintentos y tenemos datos
        if (!variant && variantsData.length > 0) {
            variant = variantsData[0];
        }

        var qty = variant ? (variant.modified ? variant.qty : 0) : 0;
        if (variant) lastConfirmedVariantId = variant.id;
        container.innerHTML = renderBadge(qty);
        // Re-agregar placeholder al DOM para próximos cambios
        if (placeholder) container.appendChild(placeholder);
        eliminarMensajeAmarillo();
    }

    function eliminarMensajeAmarillo() {
        var sels = [
            '#product_stock_availability',
            '#threshold_message',
            '.availability_messages',
            '.availability_message_undefined',
            '.availability_message_in_stock',
            '.availability_message_out_of_stock'
        ];
        sels.forEach(function(s) {
            document.querySelectorAll(s).forEach(function(el) {
                if (el.closest('.lcn-stock-container')) return;
                el.remove();
            });
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }

    // Iniciar actualización con reintentos tras carga completa
    setTimeout(function() { actualizarBadge(15); }, 300);

    document.addEventListener('change', function(e) {
        if (e.target.matches('input, select')) {
            setTimeout(actualizarBadge, 50);
            setTimeout(actualizarBadge, 200);
            setTimeout(actualizarBadge, 500);
        }
    });

    // Escuchar eventos nativos de Odoo para cambio de variante
    document.addEventListener('product_variant_change', function(e) {
        setTimeout(actualizarBadge, 50);
        setTimeout(actualizarBadge, 200);
    });

    document.addEventListener('click', function(e) {
        if (e.target.closest('.js_product, .form-check, .variant-attribute, [data-attribute]')) {
            setTimeout(actualizarBadge, 50);
            setTimeout(actualizarBadge, 200);
            setTimeout(actualizarBadge, 500);
        }
    });

    if (document.body) {
        var observer = new MutationObserver(function(mutations) {
            var cambio = false;
            mutations.forEach(function(m) {
                m.addedNodes.forEach(function(n) {
                    if (n.nodeType === 1) {
                        if (n.id === 'product_stock_availability' || n.id === 'threshold_message') {
                            cambio = true;
                        }
                    }
                });
            });
            if (cambio) {
                setTimeout(actualizarBadge, 50);
                setTimeout(actualizarBadge, 200);
            }
        });
        observer.observe(document.body, { childList: true, subtree: true });
    }

    setTimeout(init, 300);

})();
//
